/**
 * Handler for ContactTrigger. Bulk-safe: one SOQL query per context,
 * at most one DML statement in after insert.
 * Runs without sharing to preserve the original trigger's system-context behaviour.
 */
public without sharing class ContactTriggerHandler {

    /**
     * Before insert / before update: default MailingCountry from Account.BillingCountry
     * and (insert only) LeadSource from Account.AccountSource.
     */
    public static void applyAccountDefaults(List<Contact> contacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accounts = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : contacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accounts.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * After insert: if the account has no phone, set it from the first new contact
     * (in trigger order) of that account that has a phone.
     */
    public static void setAccountPhoneFromContacts(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accounts = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
        );

        Map<Id, Account> toUpdate = new Map<Id, Account>();
        for (Contact c : contacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account a = accounts.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(a.Phone)) {
                // First contact wins; later contacts see the phone already set.
                a.Phone = c.Phone;
                toUpdate.put(a.Id, a);
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate.values();
        }
    }
}
