public with sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    private static final String ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Pattern CODE_PATTERN = Pattern.compile('^[A-Z]{3}$');

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        String base = normalise(baseCurrency);
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency is required.');
        }
        Set<String> quotes = new Set<String>();
        for (String q : quoteCurrencies) {
            quotes.add(normalise(q));
        }

        HttpRequest req = new HttpRequest();
        req.setEndpoint(ENDPOINT
            + '?base=' + EncodingUtil.urlEncode(base, 'UTF-8')
            + '&symbols=' + EncodingUtil.urlEncode(String.join(new List<String>(quotes), ','), 'UTF-8'));
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');
        req.setTimeout(20000);

        Http http = new Http();
        HttpResponse res = http.send(req);
        if (res.getStatusCode() == 503) {
            res = http.send(req);
        }
        Integer status = res.getStatusCode();
        if (status != 200) {
            throw new ExchangeRateException('Exchange rate request failed with HTTP status ' + status);
        }

        Map<String, Object> rates;
        try {
            Map<String, Object> body = (Map<String, Object>) JSON.deserializeUntyped(res.getBody());
            rates = (Map<String, Object>) body.get('rates');
        } catch (Exception e) {
            throw new ExchangeRateException('Could not parse exchange rate response: ' + e.getMessage());
        }
        if (rates == null) {
            throw new ExchangeRateException('Exchange rate response contains no rates.');
        }

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String q : quotes) {
            Object v = rates.get(q);
            if (v == null) {
                throw new ExchangeRateException('No rate returned for ' + q);
            }
            try {
                result.put(q, Decimal.valueOf(String.valueOf(v)));
            } catch (Exception e) {
                throw new ExchangeRateException('Invalid rate for ' + q + ': ' + String.valueOf(v));
            }
        }
        return result;
    }

    private static String normalise(String code) {
        String c = code == null ? null : code.trim().toUpperCase();
        if (c == null || !CODE_PATTERN.matcher(c).matches()) {
            throw new ExchangeRateException('Invalid currency code: ' + code);
        }
        return c;
    }
}
