/**
 * Generic record search used by the admin "record finder" component.
 * The object name, field names and order-by field are checked against the schema
 * describe and only canonical API names are put into the query. Filter values are
 * always passed as bind variables. The query runs in USER_MODE, so record sharing,
 * object permissions and field-level security are enforced.
 */
public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    private static final Integer MAX_ROWS_LIMIT = 200;

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // ---- Row limit ----
        if (maxRows == null || maxRows < 1 || maxRows > MAX_ROWS_LIMIT) {
            throw new SearchException('maxRows must be between 1 and ' + MAX_ROWS_LIMIT + '.');
        }

        // ---- Object ----
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name is required.');
        }
        Schema.SObjectType sType = Schema.getGlobalDescribe().get(objectApiName.trim().toLowerCase());
        if (sType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }
        Schema.DescribeSObjectResult objDescribe = sType.getDescribe();
        if (!objDescribe.isAccessible() || !objDescribe.isQueryable()) {
            throw new SearchException('You do not have access to object ' + objDescribe.getName() + '.');
        }
        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

        // ---- Select fields ----
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }
        // Keys are lower-case names so duplicates are dropped; Id is always selected.
        Map<String, String> selectFields = new Map<String, String>();
        selectFields.put('id', 'Id');
        for (String f : fields) {
            Schema.DescribeFieldResult dfr = describeField(fieldMap, f, objDescribe.getName());
            selectFields.put(dfr.getName().toLowerCase(), dfr.getName());
        }

        // ---- Filters ----
        Map<String, Object> binds = new Map<String, Object>();
        List<String> conditions = new List<String>();
        if (filters != null && !filters.isEmpty()) {
            Integer i = 0;
            for (String key : filters.keySet()) {
                Schema.DescribeFieldResult dfr = describeField(fieldMap, key, objDescribe.getName());
                if (!dfr.isFilterable()) {
                    throw new SearchException('Field cannot be filtered: ' + dfr.getName());
                }
                String bindName = 'filterValue' + i;
                binds.put(bindName, filters.get(key));
                conditions.add(dfr.getName() + ' = :' + bindName);
                i++;
            }
        }

        // ---- Order by ----
        String orderClause = '';
        if (String.isNotBlank(orderByField)) {
            Schema.DescribeFieldResult dfr = describeField(fieldMap, orderByField, objDescribe.getName());
            if (!dfr.isSortable()) {
                throw new SearchException('Field cannot be sorted: ' + dfr.getName());
            }
            orderClause = ' ORDER BY ' + dfr.getName() + ' ASC';
        }

        // ---- Build the query ----
        String soql = 'SELECT ' + String.join(selectFields.values(), ', ')
            + ' FROM ' + objDescribe.getName();
        if (!conditions.isEmpty()) {
            soql += ' WHERE ' + String.join(conditions, ' AND ');
        }
        soql += orderClause + ' LIMIT ' + String.valueOf(maxRows);

        // ---- Run the query ----
        try {
            return Database.queryWithBinds(soql, binds, AccessLevel.USER_MODE);
        } catch (Exception e) {
            // Covers FLS/sharing failures and incompatible filter values.
            throw new SearchException('Search failed: ' + e.getMessage());
        }
    }

    private static Schema.DescribeFieldResult describeField(
        Map<String, Schema.SObjectField> fieldMap, String name, String objName
    ) {
        if (String.isBlank(name)) {
            throw new SearchException('Blank field name for object ' + objName + '.');
        }
        Schema.SObjectField sf = fieldMap.get(name.trim().toLowerCase());
        if (sf == null) {
            throw new SearchException('Field ' + name + ' does not exist on ' + objName + '.');
        }
        Schema.DescribeFieldResult dfr = sf.getDescribe();
        if (!dfr.isAccessible()) {
            throw new SearchException('You do not have access to field ' + dfr.getName() + '.');
        }
        return dfr;
    }
}
