public with sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body is empty');
        }
        try {
            Object root = JSON.deserializeUntyped(body);
            if (!(root instanceof Map<String, Object>)) {
                throw new PayloadException('Payload is not a JSON object');
            }
            Map<String, Object> m = (Map<String, Object>) root;

            Order o = new Order();
            o.orderNumber = scalarToString(m.get('number'), 'number');
            if (String.isBlank(o.orderNumber)) {
                throw new PayloadException('Missing order number');
            }

            String dateStr = scalarToString(m.get('date'), 'date');
            if (String.isNotBlank(dateStr)) {
                if (!Pattern.matches('\\d{4}-\\d{2}-\\d{2}', dateStr.trim())) {
                    throw new PayloadException('Invalid date: ' + dateStr);
                }
                o.orderDate = Date.valueOf(dateStr.trim());
            }

            o.currencyCode = scalarToString(m.get('currency'), 'currency');

            Object cust = m.get('customer');
            if (cust instanceof Map<String, Object>) {
                o.customerEmail = scalarToString(((Map<String, Object>) cust).get('email'), 'customer.email');
            }

            o.lines = new List<Line>();
            o.total = 0;
            Object rawLines = m.get('lines');
            if (rawLines != null) {
                if (!(rawLines instanceof List<Object>)) {
                    throw new PayloadException('lines must be an array');
                }
                Integer idx = 0;
                for (Object rl : (List<Object>) rawLines) {
                    Line ln = parseLine(rl, idx++);
                    o.lines.add(ln);
                    o.total += ln.lineTotal;
                }
            }
            o.total = o.total.setScale(2, RoundingMode.HALF_UP);
            return o;
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException('Invalid payload: ' + e.getMessage());
        }
    }

    private static Line parseLine(Object raw, Integer idx) {
        if (!(raw instanceof Map<String, Object>)) {
            throw new PayloadException('Line ' + idx + ' is not an object');
        }
        Map<String, Object> lm = (Map<String, Object>) raw;
        Line ln = new Line();

        ln.sku = scalarToString(lm.get('sku'), 'sku');
        if (String.isBlank(ln.sku)) {
            throw new PayloadException('Line ' + idx + ': missing sku');
        }

        Decimal qty = toDecimal(lm.get('quantity'), 'quantity');
        if (qty == null || qty <= 0 || qty != qty.setScale(0, RoundingMode.DOWN)) {
            throw new PayloadException('Line ' + idx + ': invalid quantity');
        }
        ln.quantity = qty.intValue();

        Decimal price = toDecimal(lm.get('unitPrice'), 'unitPrice');
        if (price == null || price < 0) {
            throw new PayloadException('Line ' + idx + ': invalid unitPrice');
        }
        ln.unitPrice = price;

        Decimal disc = toDecimal(lm.get('discount'), 'discount');
        ln.discount = disc == null ? 0 : disc;

        ln.lineTotal = (ln.quantity * ln.unitPrice * (1 - ln.discount))
            .setScale(2, RoundingMode.HALF_UP);
        return ln;
    }

    private static Decimal toDecimal(Object v, String field) {
        if (v == null) return null;
        if (v instanceof Decimal) return (Decimal) v;
        if (v instanceof Integer) return Decimal.valueOf((Integer) v);
        if (v instanceof Long) return Decimal.valueOf((Long) v);
        if (v instanceof Double) return Decimal.valueOf((Double) v);
        throw new PayloadException(field + ' must be a number');
    }

    private static String scalarToString(Object v, String field) {
        if (v == null) return null;
        if (v instanceof String) return (String) v;
        if (v instanceof Map<String, Object> || v instanceof List<Object>) {
            throw new PayloadException(field + ' must be a scalar value');
        }
        return String.valueOf(v);
    }

    public static String toAcknowledgement(Order order) {
        if (order == null) {
            throw new PayloadException('Order is null');
        }
        Map<String, Object> ack = new Map<String, Object>{
            'number' => order.orderNumber,
            'status' => 'RECEIVED',
            'lineCount' => order.lines == null ? 0 : order.lines.size(),
            'total' => order.total == null ? 0 : order.total
        };
        return JSON.serialize(ack);
    }
}
