```apex
public with sharing class AccountScoringJob implements Queueable {

    public static final Integer BATCH_SIZE = 200;
    // Developer Edition / trial orgs allow a chain depth of 5 (including the first job)
    public static final Integer MAX_CHAIN_DEPTH = 5;
    public static final Integer IDS_PER_CHAIN = BATCH_SIZE * MAX_CHAIN_DEPTH; // 1,000
    public static final Integer MAX_CHAINS = 50; // enqueueJob limit per synchronous transaction

    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds == null ? new List<Id>() : new List<Id>(accountIds);
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        // De-duplicate and drop nulls, preserving order
        List<Id> cleaned = new List<Id>();
        Set<Id> seen = new Set<Id>();
        for (Id i : accountIds) {
            if (i != null && seen.add(i)) {
                cleaned.add(i);
            }
        }
        if (cleaned.isEmpty()) {
            return null;
        }
        if (cleaned.size() > IDS_PER_CHAIN * MAX_CHAINS) {
            throw new IllegalArgumentException(
                'AccountScoringJob supports at most ' + (IDS_PER_CHAIN * MAX_CHAINS) + ' accounts.');
        }

        Id firstJobId = null;
        Integer idx = 0;
        while (idx < cleaned.size()) {
            List<Id> chunk = new List<Id>();
            Integer stop = Math.min(idx + IDS_PER_CHAIN, cleaned.size());
            for (Integer k = idx; k < stop; k++) {
                chunk.add(cleaned[k]);
            }
            idx = stop;

            Integer depth = (Integer) Math.ceil(chunk.size() / (Decimal) BATCH_SIZE);
            AsyncOptions opts = new AsyncOptions();
            opts.MaximumQueueableStackDepth = Math.max(depth, 1);

            Id jobId = System.enqueueJob(new AccountScoringJob(chunk), opts);
            if (firstJobId == null) {
                firstJobId = jobId;
            }
        }
        return firstJobId;
    }

    public void execute(QueueableContext context) {
        if (accountIds.isEmpty()) {
            return;
        }

        Set<Id> current = new Set<Id>();
        List<Id> remaining = new List<Id>();
        for (Integer i = 0; i < accountIds.size(); i++) {
            if (i < BATCH_SIZE) {
                if (accountIds[i] != null) {
                    current.add(accountIds[i]);
                }
            } else {
                remaining.add(accountIds[i]);
            }
        }

        if (!current.isEmpty()) {
            List<Account> accounts = [
                SELECT Id, AnnualRevenue, Rating
                FROM Account
                WHERE Id IN :current
            ];
            for (Account a : accounts) {
                a.Rating = rate(a.AnnualRevenue);
            }
            if (!accounts.isEmpty()) {
                update accounts;
            }
        }

        if (!remaining.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remaining));
        }
    }

    @TestVisible
    private static String rate(Decimal revenue) {
        if (revenue != null && revenue >= 1000000) {
            return 'Hot';
        }
        if (revenue != null && revenue >= 100000) {
            return 'Warm';
        }
        return 'Cold';
    }
}
```

Notes on the design:
- The finalizer is attached first in `execute`, so it runs even if the update throws.
- The update is a plain all-or-nothing `update`. A failure rolls back the job's changes and is reported as an unhandled exception to the finalizer.
- The finalizer works from the `FinalizerContext` interface methods only (`getResult`, `getException`). That lets tests pass their own implementation.
- If `getException()` is null on a failed result, the finalizer still writes a message instead of throwing.
- Building the failure log happens before the retry is enqueued, so the log is inserted whether or not a retry follows.

