/**
 * Maintains FB_Open_Pipeline__c and FB_Open_Opportunities__c on Account.
 * Runs without sharing so totals include all opportunities regardless of the running user.
 * Recalculates from the database (not deltas), so totals stay correct across any number
 * of DML statements in one transaction. Recursion through AccountTrigger is avoided by
 * processing only relevant changes and writing only accounts whose values differ.
 */
public without sharing class OpportunityPipelineHandler {

    public static void handle(System.TriggerOperation op,
                              List<Opportunity> newList,
                              Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = new Set<Id>();

        switch on op {
            when AFTER_INSERT, AFTER_UNDELETE {
                for (Opportunity o : newList) {
                    if (o.AccountId != null) {
                        accountIds.add(o.AccountId);
                    }
                }
            }
            when AFTER_DELETE {
                for (Opportunity o : oldMap.values()) {
                    if (o.AccountId != null) {
                        accountIds.add(o.AccountId);
                    }
                }
            }
            when AFTER_UPDATE {
                for (Opportunity o : newList) {
                    Opportunity old = oldMap.get(o.Id);
                    Boolean relevant =
                        o.AccountId != old.AccountId ||
                        o.Amount != old.Amount ||
                        o.StageName != old.StageName ||
                        o.IsClosed != old.IsClosed;
                    if (!relevant) {
                        continue;
                    }
                    if (o.AccountId != null) {
                        accountIds.add(o.AccountId);
                    }
                    if (old.AccountId != null) {
                        accountIds.add(old.AccountId);
                    }
                }
            }
        }

        recalculate(accountIds);
    }

    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Map<Id, Decimal> pipeline = new Map<Id, Decimal>();
        Map<Id, Integer> counts = new Map<Id, Integer>();

        for (AggregateResult ar : [
            SELECT AccountId accId, SUM(Amount) total, COUNT(Id) cnt
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('accId');
            Decimal total = (Decimal) ar.get('total');
            pipeline.put(accId, total == null ? 0 : total);
            counts.put(accId, (Integer) ar.get('cnt'));
        }

        List<Account> toUpdate = new List<Account>();
        for (Account a : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Decimal newPipeline = pipeline.containsKey(a.Id) ? pipeline.get(a.Id) : 0;
            Decimal newCount = counts.containsKey(a.Id) ? counts.get(a.Id) : 0;

            if (a.FB_Open_Pipeline__c != newPipeline || a.FB_Open_Opportunities__c != newCount) {
                toUpdate.add(new Account(
                    Id = a.Id,
                    FB_Open_Pipeline__c = newPipeline,
                    FB_Open_Opportunities__c = newCount
                ));
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
```

