/**
 * Domain class for Opportunity (Apex Enterprise Patterns / fflib).
 */
public inherited sharing class Opportunities extends fflib_SObjectDomain {

    public static final Integer DEFAULT_CLOSE_DATE_OFFSET_DAYS = 30;
    public static final String DEFAULT_TYPE = 'New Customer';

    public Opportunities(List<SObject> sObjectList) {
        super(sObjectList, Opportunity.SObjectType);
    }

    /**
     * Called by fflib only in the before insert phase, so the defaults
     * apply to new records and never to updates.
     */
    public override void onApplyDefaults() {
        Date defaultCloseDate = Date.today().addDays(DEFAULT_CLOSE_DATE_OFFSET_DAYS);
        for (SObject record : Records) {
