public with sharing class Opportunities extends fflib_SObjectDomain {

    @TestVisible
    private static final String MSG_NEGATIVE_AMOUNT = 'Amount cannot be negative.';
    @TestVisible
    private static final String MSG_WON_AMOUNT_CHANGED = 'Amount cannot change on a won opportunity.';
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public Opportunities(List<Opportunity> sObjectList) {
        super(sObjectList);
