public with sharing class OpportunityWinService {
    private static final String CLOSED_WON = 'Closed Won';

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opps = OpportunitiesSelector.newInstance().selectById(opportunityIds);

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        Date today = Date.today();
        Integer closed = 0;

        for (Opportunity opp : opps) {
            if (opp.StageName == CLOSED_WON) {
                continue;
            }
            opp.StageName = CLOSED_WON;
            opp.CloseDate = today;
            uow.registerDirty(opp);

            uow.registerPublishAfterSuccessTransaction(
                new Deal_Won__e(
                    Opportunity_Id__c = String.valueOf(opp.Id),
                    Amount__c = opp.Amount
                )
            );
            closed++;
        }

        if (closed == 0) {
            return 0;
        }

        // Single commit: DML first; after-success events are published only
        // if the DML succeeds. On failure the exception propagates and nothing is published.
        uow.commitWork();
        return closed;
    }
}
