/**
 * Normalises Contact phone numbers for the dialer.
 * The dialer accepts only digits, with an optional leading '+'.
 */
public with sharing class ContactPhoneCleanup {

    /**
     * Strips every character from Contact.Phone that the dialer cannot accept
     * and saves the changed contacts with partial success allowed.
     *
     * @param contactIds Ids of the contacts to clean (up to 200 per call).
     * @return A map from each contact that could not be saved to its first
     *         error message. The map is empty when every save succeeded.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failures = new Map<Id, String>();
        if (contactIds == null || contactIds.isEmpty()) {
            return failures;
        }

        List<Contact> toUpdate = new List<Contact>();
        for (Contact c : [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds AND Phone != null
            WITH USER_MODE
        ]) {
            String cleaned = normalize(c.Phone);
            if (cleaned != c.Phone) {
                toUpdate.add(new Contact(Id = c.Id, Phone = cleaned));
            }
        }

        if (toUpdate.isEmpty()) {
            return failures;
        }

        List<Database.SaveResult> results =
            Database.update(toUpdate, false, AccessLevel.USER_MODE);

        // A failed SaveResult has a null getId(), so take the Id from the same
        // index in the list that was saved. Results come back in that order.
        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult sr = results[i];
            if (!sr.isSuccess()) {
                List<Database.Error> errs = sr.getErrors();
                failures.put(
                    toUpdate[i].Id,
                    errs.isEmpty() ? 'Unknown error' : errs[0].getMessage()
                );
            }
        }
        return failures;
    }

    /**
     * Keeps digits only, plus one '+' when the original number started with '+'
     * (after ignoring leading spaces). Example: '+44 (20) 7946-0018' becomes
     * '+442079460018'.
     */
    @TestVisible
    private static String normalize(String phone) {
        String trimmed = phone.trim();
        String digits = trimmed.replaceAll('[^0-9]', '');
        return trimmed.startsWith('+') ? '+' + digits : digits;
    }
}
