```apex
/**
 * Closes forgotten opportunities. Called synchronously from a nightly Schedulable.
 *
 * Declared without sharing on purpose: this is a system cleanup job that must
 * process every stale opportunity regardless of who scheduled it. It is not
 * exposed to end users (no @AuraEnabled / REST entry points).
 */
public without sharing class StaleOpportunityCloser {

    public static final String CLOSED_LOST = 'Closed Lost';

    /**
     * Sets StageName = 'Closed Lost' on every open opportunity whose CloseDate is
     * strictly before the cutoff. Returns the number of opportunities actually closed.
     *
     * To stay within the synchronous DML row limit (which would otherwise throw an
     * uncatchable LimitException and roll back everything), the query is capped at
     * the remaining DML row budget. Any remainder is picked up on the next run.
     */
    public static Integer closeStale(Date cutoff) {
        if (cutoff == null) {
            return 0;
        }

        Integer rowBudget = Limits.getLimitDmlRows() - Limits.getDmlRows();
        if (rowBudget <= 0) {
            return 0;
        }

        Integer closedCount = 0;

        // List-form SOQL for loop: records arrive in chunks of 200, so we never
        // hold the full result set in memory, and we issue one DML per chunk.
        for (List<Opportunity> chunk : [
                SELECT Id, StageName
                FROM Opportunity
                WHERE IsClosed = false
                  AND CloseDate < :cutoff
                LIMIT :rowBudget
        ]) {
            for (Opportunity opp : chunk) {
                opp.StageName = CLOSED_LOST;
            }

            // allOrNone = false: a single bad record (validation rule, trigger
            // error) must not roll back the whole nightly run.
            List<Database.SaveResult> results = Database.update(chunk, false);
            for (Integer i = 0; i < results.size(); i++) {
                Database.SaveResult sr = results[i];
                if (sr.isSuccess()) {
                    closedCount++;
                } else {
                    for (Database.Error err : sr.getErrors()) {
                        System.debug(LoggingLevel.ERROR,
                            'StaleOpportunityCloser: could not close ' + chunk[i].Id
                            + ': ' + err.getStatusCode() + ' - ' + err.getMessage());
                    }
                }
            }
        }

        return closedCount;
    }
}
```

