/**
 * Sets Case.Priority to 'High' for new cases whose Account has Rating = 'Hot'.
 * All other cases (including those without an Account) keep their original Priority.
 *
 * Bulk-safe: uses a single SOQL query regardless of how many cases are inserted
 * (the ERP integration inserts up to 200 at a time; a query per case would exceed
 * the 100-SOQL-per-transaction limit).
 *
 * Declared "without sharing" on purpose: the priority rule must apply even if the
 * creating user/integration cannot see the Account. Only Account.Rating is read.
 */
public without sharing class CasePriorityHandler {

    private static final String HOT_RATING = 'Hot';
    private static final String HIGH_PRIORITY = 'High';

    public static void setPriorityFromAccountRating(List<Case> newCases) {
        // Step 1: collect the Account Ids referenced by the new cases.
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        // Cases without accounts need no work.
        if (accountIds.isEmpty()) {
            return;
        }

        // Step 2: ONE query for all related accounts.
        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Rating FROM Account WHERE Id IN :accountIds]
        );

        // Step 3: set Priority on cases whose account is Hot.
        for (Case c : newCases) {
            if (c.AccountId == null) {
                continue;
            }
            Account acc = accountsById.get(c.AccountId);
            if (acc != null && acc.Rating == HOT_RATING) {
                c.Priority = HIGH_PRIORITY;
            }
        }
    }
}
```

