trigger CaseTrigger on Case (after update) {
    Set<Id> newlyClosed = new Set<Id>();
    for (Case c : Trigger.new) {
        Case oldC = Trigger.oldMap.get(c.Id);
        if (c.IsClosed && !oldC.IsClosed && c.ContactId != null) {
            newlyClosed.add(c.Id);
        }
    }
    if (newlyClosed.isEmpty()) {
        return;
    }

    CaseSurveyJob job = new CaseSurveyJob(newlyClosed);
    if (Limits.getQueueableJobs() < Limits.getLimitQueueableJobs()) {
        System.enqueueJob(job);
    } else {
        // No queueable capacity left in this transaction (e.g. already async):
        // fall back to inline processing so no survey is lost.
        job.execute(null);
    }
}
