```apex
public with sharing class CaseSurveyJob implements Queueable, Database.AllowsCallouts {

    private final Set<Id> caseIds;

    public CaseSurveyJob(Id caseId) {
        this(new Set<Id>{ caseId });
    }

    public CaseSurveyJob(Set<Id> caseIds) {
        this.caseIds = caseIds == null ? new Set<Id>() : new Set<Id>(caseIds);
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
              AND IsClosed = true
              AND ContactId != null
        ];

        List<Task> tasks = new List<Task>();
        Date due = Date.today().addDays(2);
        for (Case c : cases) {
            tasks.add(new Task(
                WhatId = c.Id,
                WhoId = c.ContactId,
                Subject = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = due,
                Status = 'Not Started'
            ));
        }
        if (tasks.isEmpty()) {
            return;
        }

        // Partial success: one bad record must not block surveys for other cases.
        Database.SaveResult[] results = Database.insert(tasks, false);
        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                for (Database.Error err : results[i].getErrors()) {
                    System.debug(LoggingLevel.ERROR,
                        'CSAT task failed for case ' + tasks[i].WhatId + ': ' + err.getMessage());
                }
            }
        }
    }
}
