/**
 * Sends renewal reminder emails to opportunity owners.
 *
 * All messages are sent in ONE Messaging.sendEmail call with allOrNothing = false.
 * Calling sendEmail per record would hit the 10-sendEmail-calls-per-transaction
 * limit (an uncatchable LimitException) for batches larger than 10.
 * Partial success still isolates failures per email.
 */
public inherited sharing class RenewalReminderService {

    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Set<Id> idSet = new Set<Id>(opportunityIds);
        idSet.remove(null);
        if (idSet.isEmpty()) {
            return 0;
        }

        List<Opportunity> opps = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :idSet
              AND Owner.IsActive = true
        ];

        List<Messaging.SingleEmailMessage> messages = new List<Messaging.SingleEmailMessage>();
        for (Opportunity opp : opps) {
            Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();
            mail.setTargetObjectId(opp.OwnerId);
            mail.setSaveAsActivity(false);
            mail.setSubject('Renewal due: ' + opp.Name);
            String closeDateText = opp.CloseDate != null ? opp.CloseDate.format() : 'not set';
            mail.setPlainTextBody(
                'The opportunity "' + opp.Name + '" is due for renewal.\n' +
                'Close date: ' + closeDateText + '\n\n' +
                'Please review it and follow up with the customer.'
            );
            messages.add(mail);
        }

        if (messages.isEmpty()) {
            return 0;
        }

        Integer sent = 0;
        List<Messaging.SendEmailResult> results = Messaging.sendEmail(messages, false);
        for (Integer i = 0; i < results.size(); i++) {
            Messaging.SendEmailResult res = results[i];
            if (res.isSuccess()) {
                sent++;
            } else {
                for (Messaging.SendEmailError err : res.getErrors()) {
                    System.debug(LoggingLevel.ERROR,
                        'Renewal reminder failed for opportunity ' + opps[i].Id +
                        ': ' + err.getStatusCode() + ' - ' + err.getMessage());
                }
            }
        }
        return sent;
    }
}
