```apex
/**
 * Keeps Contact.MailingCountry in sync with Account.BillingCountry when an
 * account's BillingCountry changes.
 *
 * Contacts are updated only when their MailingCountry is blank or equals the
 * account's previous BillingCountry. Contacts based elsewhere are left alone.
 *
 * Runs without sharing on purpose: this is a data-consistency rule that must
 * apply to all contacts of the account, whoever triggers the update.
 */
public without sharing class AccountCountrySync {

    public static void syncContactCountries(List<Account> newAccounts, Map<Id, Account> oldMap) {
        // 1. Collect only the accounts whose BillingCountry actually changed.
        Map<Id, Account> changedAccounts = new Map<Id, Account>();
        for (Account acc : newAccounts) {
            Account oldAcc = oldMap.get(acc.Id);
            if (oldAcc != null && !sameCountry(acc.BillingCountry, oldAcc.BillingCountry)) {
                changedAccounts.put(acc.Id, acc);
            }
        }
        if (changedAccounts.isEmpty()) {
            return; // nothing to do, no query spent
        }

        // 2. One selective query, limited to contacts of the changed accounts.
        //    (Never query the whole Contact table: 50,000 row limit.)
        List<Contact> toUpdate = new List<Contact>();
        for (Contact c : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccounts.keySet()
        ]) {
            String oldCountry = oldMap.get(c.AccountId).BillingCountry;
            String newCountry = changedAccounts.get(c.AccountId).BillingCountry;

            if (String.isBlank(c.MailingCountry) || sameCountry(c.MailingCountry, oldCountry)) {
                if (!sameCountry(c.MailingCountry, newCountry)) {
                    toUpdate.add(new Contact(Id = c.Id, MailingCountry = newCountry));
                }
            }
        }

        // 3. Single DML statement.
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }

    /** Treats null and blank as equal; Apex String == is case-insensitive. */
    private static Boolean sameCountry(String a, String b) {
        if (String.isBlank(a) && String.isBlank(b)) {
            return true;
        }
        if (String.isBlank(a) || String.isBlank(b)) {
            return false;
        }
        return a.trim() == b.trim();
    }
}
```

