import { LightningElement, api, wire } from 'lwc';
import { getRecord, getFieldValue } from 'lightning/uiRecordApi';
import NAME_FIELD from '@salesforce/schema/Account.Name';
import INDUSTRY_FIELD from '@salesforce/schema/Account.Industry';
import REVENUE_FIELD from '@salesforce/schema/Account.AnnualRevenue';
import OWNER_NAME_FIELD from '@salesforce/schema/Account.Owner.Name';

const FIELDS = [NAME_FIELD, INDUSTRY_FIELD, REVENUE_FIELD, OWNER_NAME_FIELD];

export default class AccountHeader extends LightningElement {
    @api recordId;

    @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
    account;

    get hasData() {
        return !!(this.account && this.account.data);
    }

    get hasError() {
        return !!(this.account && this.account.error);
    }

    get isLoading() {
        return !this.hasData && !this.hasError;
    }

    get errorMessage() {
        const err = this.account && this.account.error;
        if (!err) {
            return '';
        }
        return err.body && err.body.message ? err.body.message : 'Unknown error';
    }

    get name() {
        return this.hasData ? getFieldValue(this.account.data, NAME_FIELD) : undefined;
    }

    get industry() {
        return this.hasData ? getFieldValue(this.account.data, INDUSTRY_FIELD) : undefined;
    }

    get hasIndustry() {
        const value = this.industry;
        return value !== null && value !== undefined && value !== '';
    }

    get annualRevenue() {
        return this.hasData ? getFieldValue(this.account.data, REVENUE_FIELD) : undefined;
    }

    get ownerName() {
        return this.hasData ? getFieldValue(this.account.data, OWNER_NAME_FIELD) : undefined;
    }
}
