```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_MS = 300;

export default class ContactSearch extends LightningElement {
    contacts = [];
    errorMessage;

    _timeoutId;
    _requestId = 0;

    get hasContacts() {
        return Array.isArray(this.contacts) && this.contacts.length > 0;
    }

    handleChange(event) {
        const raw = event.detail && event.detail.value !== undefined
            ? event.detail.value
            : event.target.value;
        const term = (raw || '').trim();

        this._cancelPending();

        if (term.length < 2) {
            // Invalidate any in-flight request so its response is ignored.
            this._requestId++;
            this.contacts = [];
            this.errorMessage = undefined;
            return;
        }

        // eslint-disable-next-line @lwc/lwc/no-async-operation
        this._timeoutId = setTimeout(() => {
            this._timeoutId = undefined;
            this._runSearch(term);
        }, DEBOUNCE_MS);
    }

    async _runSearch(searchTerm) {
        const requestId = ++this._requestId;
        try {
            const result = await searchContacts({ searchTerm });
            if (requestId !== this._requestId) {
                return;
            }
            this.contacts = result || [];
            this.errorMessage = undefined;
        } catch (error) {
            if (requestId !== this._requestId) {
                return;
            }
            this.contacts = [];
            this.errorMessage =
                (error && error.body && error.body.message) ||
                (error && error.message) ||
                'Unknown error';
        }
    }

    _cancelPending() {
        if (this._timeoutId) {
            clearTimeout(this._timeoutId);
            this._timeoutId = undefined;
        }
    }

    disconnectedCallback() {
        this._cancelPending();
        // Ignore any responses still in flight.
        this._requestId++;
    }
}
