    }

    handleReset() {
        this.editors.forEach((editor) => editor.reset());
    }

    handleSubmit() {
        const editors = this.editors;
        let allValid = true;
        // Validate every editor (no short-circuit) so all errors display at once.
        editors.forEach((editor) => {
            const valid = editor.validate();
            if (!valid) {
                allValid = false;
            }
        });

        if (!allValid) {
            this.showError = true;
            return;
        }

        this.showError = false;
        const lines = editors.map((editor) => editor.getValue());
        this.dispatchEvent(new CustomEvent('submit', { detail: { lines } }));
    }
}
