import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const POLL_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    stats;
    errorMessage;

    _intervalId = null;
    _inFlight = false;
    _connected = false;

    _handleVisibilityChange = () => {
        if (document.visibilityState === 'hidden') {
            this._stopPolling();
        } else {
            this._loadStats();
            this._startPolling();
        }
    };

    connectedCallback() {
        this._connected = true;
        document.addEventListener('visibilitychange', this._handleVisibilityChange);
        if (document.visibilityState !== 'hidden') {
            this._loadStats();
            this._startPolling();
        }
    }

    disconnectedCallback() {
        this._connected = false;
        document.removeEventListener('visibilitychange', this._handleVisibilityChange);
        this._stopPolling();
    }

    get hasStats() {
        return this.stats != null;
    }

    get waiting() {
        return this.stats ? this.stats.waiting : null;
    }

    get longestWaitMinutes() {
        return this.stats ? this.stats.longestWaitMinutes : null;
    }

    _startPolling() {
        this._stopPolling();
        // eslint-disable-next-line @lwc/lwc/no-async-operation
        this._intervalId = setInterval(() => {
            this._loadStats();
        }, POLL_INTERVAL_MS);
    }

    _stopPolling() {
        if (this._intervalId !== null) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }
    }

    async _loadStats() {
        if (!this._connected || this._inFlight || document.visibilityState === 'hidden') {
            return;
        }
        this._inFlight = true;
        try {
            const result = await getQueueStats();
            if (this._connected) {
