import register from '@salesforce/apex/RegistrationController.register';

const BLOCKED_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';
    isSubmitting = false;

    handleChange(event) {
        const field = event.target.dataset.field;
        if (field) {
            this[field] = event.detail.value;
        }
    }

    async handleRegister() {
        const emailInput = this.template.querySelector('lightning-input[data-field="email"]');
        if (emailInput) {
            const value = (this.email || '').trim();
            const at = value.lastIndexOf('@');
            const domain = at >= 0 ? value.substring(at + 1).trim().toLowerCase() : '';
            if (BLOCKED_DOMAINS.includes(domain)) {
                emailInput.setCustomValidity('Use your work email address.');
            } else {
                emailInput.setCustomValidity('');
            }
        }

        const inputs = [...this.template.querySelectorAll('lightning-input')];
        const allValid = inputs.reduce((valid, input) => input.reportValidity() && valid, true);
        if (!allValid) {
            return;
        }

        this.isSubmitting = true;
        try {
            await register({
                fullName: this.fullName,
                email: this.email,
                company: this.company
            });
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    message: 'You are registered for the event.',
                    variant: 'success'
                })
            );
        } catch (error) {
            const message =
