```javascript
import { LightningElement, api } from 'lwc';

const HANDLED_KEYS = new Set(['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' ']);

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value;
    _activeIndex = 0;

    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = Array.isArray(val) ? val : [];
        this._resetActive();
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        this._resetActive();
    }

    _indexOfValue(val) {
        if (val === undefined || val === null || val === '') {
            return -1;
        }
        return this._options.findIndex((o) => o && o.value === val);
    }

    _resetActive() {
        const idx = this._indexOfValue(this._value);
        this._activeIndex = idx >= 0 ? idx : 0;
    }

    get _boundedActiveIndex() {
        const len = this._options.length;
        if (len === 0) {
            return -1;
        }
        return Math.min(Math.max(this._activeIndex, 0), len - 1);
    }

    get viewOptions() {
        const active = this._boundedActiveIndex;
        return this._options.map((opt, index) => {
            const selected = opt.value === this._value && this._indexOfValue(this._value) === index;
            const isActive = index === active;
            let cls = 'slds-listbox__item';
            if (isActive) cls += ' slds-has-focus';
            if (selected) cls += ' slds-is-selected';
            return {
                key: `opt-${index}`,
                id: `option-${index}`,
                index,
                value: opt.value,
                label: opt.label,
                ariaSelected: selected ? 'true' : 'false',
                className: cls
            };
        });
    }

    get activeDescendant() {
        const active = this._boundedActiveIndex;
        return active >= 0 ? `option-${active}` : undefined;
    }

    handleKeyDown(event) {
        const key = event.key;
        if (!HANDLED_KEYS.has(key)) {
            return;
        }
        event.preventDefault();
        const len = this._options.length;
        if (len === 0) {
            return;
        }
        const current = this._boundedActiveIndex;
        switch (key) {
            case 'ArrowDown':
                this._activeIndex = Math.min(current + 1, len - 1);
                break;
            case 'ArrowUp':
                this._activeIndex = Math.max(current - 1, 0);
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = len - 1;
                break;
            default:
                this._select(current);
        }
    }

    handleOptionClick(event) {
        const index = parseInt(event.currentTarget.dataset.index, 10);
        if (Number.isNaN(index) || index < 0 || index >= this._options.length) {
            return;
        }
        this._activeIndex = index;
        this._select(index);
    }

    _select(index) {
        const opt = this._options[index];
        if (!opt) {
            return;
        }
        this._activeIndex = index;
        if (this._indexOfValue(this._value) === index) {
            return;
        }
        this._value = opt.value;
        this.dispatchEvent(new CustomEvent('change', { detail: { value: opt.value } }));
    }
}
