import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;

    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this._tasks;
    }
    set tasks(value) {
        this._tasks = value;
        this.items = Array.isArray(value) ? value.map((task) => ({ ...task })) : [];
    }

    get displayHeading() {
        return this.heading ? String(this.heading).toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    generateId() {
        let id;
        do {
            id = `new-${this.nextId++}`;
        } while (this.items.some((t) => String(t.id) === id));
        return id;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            return;
        }
        this.items = [...this.items, { id: this.generateId(), label, done: false }];
        this.newLabel = '';
        const input = this.template.querySelector('lightning-input.new-task');
        if (input) {
            input.value = '';
        }
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        const checked = event.target.checked;
        this.items = this.items.map((t) =>
            String(t.id) === id
                ? { ...t, done: typeof checked === 'boolean' ? checked : !t.done }
                : t
        );
    }
}
