/**
 * Sets each contact's current employer using NPSP's standard affiliation mechanism.
 *
 * For each contact we save a Current, Primary npe5__Affiliation__c to the organization.
 * NPSP's affiliation trigger handler (AFFL_Affiliations_TDTM) then does the rest:
 *  - it sets Contact.npsp__Primary_Affiliation__c to the organization;
 *  - it changes the previous primary affiliation to Former and non-primary, with an
 *    end date of today.
 * Contact.AccountId is never changed, so the contact stays in their household.
 *
 * Limits used by this class: 2 SOQL queries and at most 2 DML statements
 * (NPSP's trigger work is in addition to this).
 */
public inherited sharing class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Drop null keys and values.
        Map<Id, Id> requested = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id orgId = employerByContactId.get(contactId);
            if (contactId != null && orgId != null) {
                requested.put(contactId, orgId);
            }
        }
        if (requested.isEmpty()) {
            return;
        }

        // SOQL 1: the contacts and their current primary affiliation lookup.
        Map<Id, Contact> contacts = new Map<Id, Contact>([
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :requested.keySet()
        ]);

        // SOQL 2: existing affiliations between these contacts and the requested organizations.
        Set<Id> orgIds = new Set<Id>(requested.values());
        Map<Id, npe5__Affiliation__c> existingByContact = new Map<Id, npe5__Affiliation__c>();
        for (npe5__Affiliation__c a : [
            SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Status__c,
                   npe5__Primary__c, npe5__EndDate__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :requested.keySet()
              AND npe5__Organization__c IN :orgIds
            ORDER BY npe5__Primary__c DESC, LastModifiedDate DESC
        ]) {
            // Only keep affiliations to the organization requested for this contact.
            if (requested.get(a.npe5__Contact__c) != a.npe5__Organization__c) {
                continue;
            }
            npe5__Affiliation__c best = existingByContact.get(a.npe5__Contact__c);
            if (best == null || rank(a) > rank(best)) {
                existingByContact.put(a.npe5__Contact__c, a);
            }
        }

        List<npe5__Affiliation__c> toInsert = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> toUpdate = new List<npe5__Affiliation__c>();

        for (Id contactId : requested.keySet()) {
            Contact c = contacts.get(contactId);
            if (c == null) {
                continue; // contact not found or not visible
            }
            Id orgId = requested.get(contactId);
            npe5__Affiliation__c existing = existingByContact.get(contactId);

            // Already the current primary employer: change nothing.
            if (existing != null
                    && c.npsp__Primary_Affiliation__c == orgId
                    && existing.npe5__Primary__c
                    && existing.npe5__Status__c == 'Current') {
                continue;
            }

            if (existing != null) {
                // Reuse the existing affiliation so we don't create a duplicate.
                toUpdate.add(new npe5__Affiliation__c(
                    Id = existing.Id,
                    npe5__Status__c = 'Current',
                    npe5__Primary__c = true,
                    npe5__EndDate__c = null
                ));
            } else {
                toInsert.add(new npe5__Affiliation__c(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = orgId,
                    npe5__Status__c = 'Current',
                    npe5__Primary__c = true,
                    npe5__StartDate__c = Date.today()
                ));
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;   // DML 1
        }
        if (!toInsert.isEmpty()) {
            insert toInsert;   // DML 2
        }
    }

    /** Prefers a current primary affiliation, then any current one, then any other. */
    private static Integer rank(npe5__Affiliation__c a) {
        Integer r = 0;
        if (a.npe5__Status__c == 'Current') {
            r += 2;
        }
        if (a.npe5__Primary__c) {
            r += 1;
        }
        return r;
    }
}
```

**Design notes**

- **NPSP does the bookkeeping.** The class saves a Current, Primary affiliation for each contact. NPSP's affiliation trigger then sets `npsp__Primary_Affiliation__c` and closes out the old primary as Former, non-primary, with an end date of today.
- **Household is safe.** `Contact.AccountId` is never touched, so each contact stays in their household account.
- **No duplicates.**
  - If the organization is already the contact's primary lookup and has a Current, Primary affiliation, the contact is skipped.
  - If a Former or non-primary affiliation to that organization already exists, it is reactivated instead of inserting a new one.
- **Limits.** The class uses 2 SOQL queries and at most 2 DML statements (one update, one insert), so 200 contacts work in one call. Null or empty input returns straight away.
- **Assumption.** A contact Id that isn't found, or isn't visible to the running user, is skipped silently rather than raising an error.

