/**
 * Splits an Opportunity across NPSP General Accounting Units by percentage.
 *
 * Allocations are stored with npsp__Percent__c only and npsp__Amount__c is left
 * blank. NPSP's allocation triggers calculate each amount from the Opportunity
 * amount. They recalculate it whenever the Opportunity amount changes, so the
 * split stays correct with no extra code.
 */
public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        // ---------- Validation (no data changes before this is complete) ----------
        if (opportunityId == null) {
            throw new AllocationException('An Opportunity Id is required.');
        }
        if (opportunityId.getSObjectType() != Opportunity.SObjectType) {
            throw new AllocationException('The Id provided is not an Opportunity Id.');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU allocation percentage is required.');
        }

        Decimal total = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('A General Accounting Unit Id must not be null.');
            }
            if (gauId.getSObjectType() != npsp__General_Accounting_Unit__c.SObjectType) {
                throw new AllocationException('Id ' + gauId + ' is not a General Accounting Unit Id.');
            }
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException('Percentage for GAU ' + gauId + ' must be greater than 0.');
            }
            total += pct;
        }
        if (total > 100) {
            throw new AllocationException('Allocation percentages total ' + total + '%, which exceeds 100%.');
        }

        List<Opportunity> opps = [SELECT Id FROM Opportunity WHERE Id = :opportunityId LIMIT 1];
        if (opps.isEmpty()) {
            throw new AllocationException('Opportunity ' + opportunityId + ' was not found.');
        }

        Map<Id, npsp__General_Accounting_Unit__c> gaus = new Map<Id, npsp__General_Accounting_Unit__c>(
            [SELECT Id, Name, npsp__Active__c
             FROM npsp__General_Accounting_Unit__c
             WHERE Id IN :percentByGauId.keySet()]
        );
        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gaus.get(gauId);
            if (gau == null) {
                throw new AllocationException('General Accounting Unit ' + gauId + ' was not found.');
            }
            if (!gau.npsp__Active__c) {
                throw new AllocationException('General Accounting Unit "' + gau.Name + '" is inactive.');
            }
        }

        // ---------- Build new allocations (percent only; NPSP calculates the amount) ----------
        List<npsp__Allocation__c> toInsert = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            toInsert.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            ));
        }

        List<npsp__Allocation__c> existing = [
            SELECT Id FROM npsp__Allocation__c WHERE npsp__Opportunity__c = :opportunityId
        ];

        // ---------- Replace atomically ----------
        Savepoint sp = Database.setSavepoint();
        try {
            if (!existing.isEmpty()) {
                delete existing;
            }
            insert toInsert;
        } catch (Exception e) {
            Database.rollback(sp);
            throw new AllocationException('Failed to save GAU allocations: ' + e.getMessage(), e);
        }

        // Re-query so callers see the amounts NPSP calculated.
        Set<Id> newIds = new Map<Id, npsp__Allocation__c>(toInsert).keySet();
        return [
            SELECT Id, npsp__Opportunity__c, npsp__General_Accounting_Unit__c,
                   npsp__Percent__c, npsp__Amount__c
            FROM npsp__Allocation__c
            WHERE Id IN :newIds
        ];
    }
}
