/**
 * Creates a single NPSP Household Account for a list of new contacts.
 * The first contact becomes the household's primary contact.
 */
public with sharing class HouseholdService {

    private static final String HH_RECORD_TYPE_DEV_NAME = 'HH_Account';

    public class HouseholdServiceException extends Exception {}

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must contain at least one Contact.');
        }
        for (Contact c : members) {
            if (c == null) {
                throw new IllegalArgumentException('members must not contain null entries.');
            }
            if (c.Id != null) {
                throw new IllegalArgumentException('members must be new (uninserted) Contacts.');
            }
        }

        Schema.RecordTypeInfo hhInfo = Schema.SObjectType.Account
            .getRecordTypeInfosByDeveloperName()
            .get(HH_RECORD_TYPE_DEV_NAME);
        if (hhInfo == null) {
            throw new HouseholdServiceException(
                'Account record type ' + HH_RECORD_TYPE_DEV_NAME + ' not found.');
        }
        Id hhRecordTypeId = hhInfo.getRecordTypeId();

        Savepoint sp = Database.setSavepoint();
        try {
            // 1. Insert the primary contact without an account: NPSP creates
            //    exactly one Household Account for it, names it and sets it as primary.
            Contact primary = members[0];
            primary.AccountId = null;
            insert primary;

            Contact insertedPrimary = [
                SELECT Id, AccountId
                FROM Contact
                WHERE Id = :primary.Id
                LIMIT 1
            ];
            Id householdId = insertedPrimary.AccountId;
            if (householdId == null) {
                throw new HouseholdServiceException(
                    'NPSP did not create a household. Check that the Household Account model is enabled.');
            }

            Account household = [
                SELECT Id, RecordTypeId, npe01__One2OneContact__c
                FROM Account
                WHERE Id = :householdId
                LIMIT 1
            ];
            if (household.RecordTypeId != hhRecordTypeId) {
                throw new HouseholdServiceException(
                    'The auto-created account is not an NPSP Household Account (' +
                    HH_RECORD_TYPE_DEV_NAME + ').');
            }
            primary.AccountId = householdId;

            // 2. Insert remaining members directly into the household (bulk, one DML).
            //    Contacts that already have an AccountId get no new household from NPSP.
            if (members.size() > 1) {
                List<Contact> others = new List<Contact>();
                for (Integer i = 1; i < members.size(); i++) {
                    Contact c = members[i];
                    c.AccountId = householdId;
                    others.add(c);
                }
                insert others;
            }

            // 3. Make sure the first contact is the primary contact. The account name
            //    is not touched; NPSP maintains names and greetings.
            if (household.npe01__One2OneContact__c != primary.Id) {
                update new Account(Id = householdId, npe01__One2OneContact__c = primary.Id);
            }

            return householdId;
        } catch (Exception e) {
            Database.rollback(sp);
            // Clear Ids assigned before the rollback so callers can retry safely.
            for (Contact c : members) {
                c.Id = null;
                c.AccountId = null;
            }
            throw e;
        }
    }
}
