/**
 * Creates or updates NPSP partial soft credits for peer-to-peer fundraisers.
 * Per call: 3 SOQL queries and at most 3 DML statements, regardless of batch size.
 */
public inherited sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    private static String key(Id oppId, Id contactId) {
        return String.valueOf(oppId) + ':' + String.valueOf(contactId);
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest r : requests) {
            if (r == null || r.opportunityId == null || r.contactId == null) {
                throw new SoftCreditException('Each request needs an opportunityId and a contactId.');
            }
            oppIds.add(r.opportunityId);
            contactIds.add(r.contactId);
        }

        // Query 1: opportunities
        Map<Id, Opportunity> opps = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c
             FROM Opportunity WHERE Id IN :oppIds]
        );

        // Validate everything before any DML
        for (SoftCreditRequest r : requests) {
            Opportunity opp = opps.get(r.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + r.opportunityId);
            }
            if (opp.npsp__Primary_Contact__c == r.contactId) {
                throw new SoftCreditException('Contact ' + r.contactId
                    + ' is the primary contact of opportunity ' + r.opportunityId + '.');
            }
            if (r.amount == null || r.amount <= 0) {
                throw new SoftCreditException('Soft credit amount must be positive for contact '
                    + r.contactId + '.');
            }
            if (opp.Amount == null || r.amount > opp.Amount) {
                throw new SoftCreditException('Soft credit amount exceeds the opportunity amount for opportunity '
                    + r.opportunityId + '.');
            }
        }

        // Query 2: existing partial soft credits
        Map<String, npsp__Partial_Soft_Credit__c> pscByKey = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
                SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                       npsp__Role_Name__c, npsp__Contact_Role_ID__c
                FROM npsp__Partial_Soft_Credit__c
                WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds]) {
            String k = key(psc.npsp__Opportunity__c, psc.npsp__Contact__c);
            if (!pscByKey.containsKey(k)) {
                pscByKey.put(k, psc);
            }
        }

        // Query 3: existing contact roles
        Map<String, List<OpportunityContactRole>> ocrsByKey = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
                SELECT Id, OpportunityId, ContactId, Role
                FROM OpportunityContactRole
                WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
                ORDER BY CreatedDate ASC]) {
            String k = key(ocr.OpportunityId, ocr.ContactId);
            if (!ocrsByKey.containsKey(k)) {
                ocrsByKey.put(k, new List<OpportunityContactRole>());
            }
            ocrsByKey.get(k).add(ocr);
        }

        List<OpportunityContactRole> ocrsToDelete = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToUpsert = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> keptOcr = new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest r : requests) {
            String k = key(r.opportunityId, r.contactId);
            List<OpportunityContactRole> existing = ocrsByKey.get(k);
            npsp__Partial_Soft_Credit__c psc = pscByKey.get(k);
            OpportunityContactRole keep = null;

            if (existing != null && !existing.isEmpty()) {
                // Keep the OCR the existing soft credit points to, then one with the role, then the oldest
                if (psc != null && psc.npsp__Contact_Role_ID__c != null) {
                    for (OpportunityContactRole o : existing) {
                        if (String.valueOf(o.Id).substring(0, 15)
                                == psc.npsp__Contact_Role_ID__c.left(15)) {
                            keep = o;
                            break;
                        }
                    }
                }
                if (keep == null) {
                    for (OpportunityContactRole o : existing) {
                        if (o.Role == r.role) { keep = o; break; }
                    }
                }
                if (keep == null) {
                    keep = existing[0];
                }
                for (OpportunityContactRole o : existing) {
                    if (o.Id != keep.Id) {
                        ocrsToDelete.add(new OpportunityContactRole(Id = o.Id));
                    }
                }
                if (keep.Role != r.role) {
                    keep.Role = r.role;
                    ocrsToUpsert.add(keep);
                }
            } else {
                keep = new OpportunityContactRole(
                    OpportunityId = r.opportunityId,
                    ContactId = r.contactId,
                    Role = r.role
                );
                ocrsToUpsert.add(keep);
            }
            keptOcr.put(k, keep);
        }

        Savepoint sp = Database.setSavepoint();
        try {
            if (!ocrsToDelete.isEmpty()) {
                delete ocrsToDelete;
            }
            if (!ocrsToUpsert.isEmpty()) {
                upsert ocrsToUpsert; // inserts new and updates existing in one DML
            }

            // Re-read soft credits after OCR DML is not needed: we upsert by Id when known
            List<npsp__Partial_Soft_Credit__c> pscsToUpsert = new List<npsp__Partial_Soft_Credit__c>();
            for (SoftCreditRequest r : requests) {
                String k = key(r.opportunityId, r.contactId);
                OpportunityContactRole ocr = keptOcr.get(k);
                npsp__Partial_Soft_Credit__c existingPsc = pscByKey.get(k);
                npsp__Partial_Soft_Credit__c psc = existingPsc != null
                    ? new npsp__Partial_Soft_Credit__c(Id = existingPsc.Id)
                    : new npsp__Partial_Soft_Credit__c(
                        npsp__Opportunity__c = r.opportunityId,
                        npsp__Contact__c = r.contactId);
                psc.npsp__Amount__c = r.amount;
                psc.npsp__Role_Name__c = r.role;
                psc.npsp__Contact_Role_ID__c = ocr.Id;
                pscsToUpsert.add(psc);
            }
            upsert pscsToUpsert;
        } catch (Exception e) {
            Database.rollback(sp);
            throw new SoftCreditException('Failed to save partial soft credits: ' + e.getMessage(), e);
        }
    }
}
```

Notes:
- **Which contact role is kept:** if a contact has several roles on one opportunity, the class keeps one and deletes the rest. It keeps, in order of preference:
  1. the role already linked from an existing soft credit;
  2. otherwise a role whose name already matches the requested role;
  3. otherwise the oldest role.

  Keeping the linked role avoids the NPSP delete cascade removing that soft credit. The kept role is then given the requested name.
- **Failure handling:** a savepoint rolls back all changes if any DML fails, so the call either fully succeeds or changes nothing.
- **Contact name field:** `npsp__Contact_Name__c` is left for NPSP to populate.

