/**
 * Records an already-received gift the way NPSP expects:
 * household account, primary contact = Donor, other household members = Household Member,
 * and exactly one paid payment for the full amount.
 *
 * NPSP triggers may already create contact roles and a payment when the Opportunity is inserted.
 * This service therefore reconciles after insert rather than blindly inserting, so there are
 * never duplicate roles or payments.
 */
public with sharing class GiftService {

    private static final String ROLE_DONOR = 'Donor';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('contactId is required.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('giftDate is required.');
        }

        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact not found: ' + contactId);
        }
        Contact donor = contacts[0];
        if (donor.AccountId == null) {
            throw new IllegalArgumentException('Contact has no household account: ' + contactId);
        }

        String closedWonStage = getClosedWonStage();

        Savepoint sp = Database.setSavepoint();
        try {
            Opportunity opp = new Opportunity(
                Name = buildName(donor, giftDate),
                AccountId = donor.AccountId,
                npsp__Primary_Contact__c = donor.Id,
                Amount = amount,
                CloseDate = giftDate,
                StageName = closedWonStage
            );
            insert opp;

            reconcileContactRoles(opp.Id, donor);
            reconcilePayment(opp.Id, amount, giftDate);

            return opp.Id;
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }
    }

    private static void reconcileContactRoles(Id oppId, Contact donor) {
        Map<Id, String> desiredRoles = new Map<Id, String>();
        for (Contact member : [
            SELECT Id FROM Contact WHERE AccountId = :donor.AccountId
        ]) {
            desiredRoles.put(member.Id, ROLE_HOUSEHOLD_MEMBER);
        }
        desiredRoles.put(donor.Id, ROLE_DONOR);

        // Group existing roles (possibly created by NPSP) by contact.
        Map<Id, List<OpportunityContactRole>> existingByContact =
            new Map<Id, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :oppId
            ORDER BY CreatedDate ASC, Id ASC
        ]) {
            if (!existingByContact.containsKey(ocr.ContactId)) {
                existingByContact.put(ocr.ContactId, new List<OpportunityContactRole>());
            }
            existingByContact.get(ocr.ContactId).add(ocr);
        }

        List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();

        // Contacts outside the household: keep at most one role each.
        for (Id cId : existingByContact.keySet()) {
            if (!desiredRoles.containsKey(cId)) {
                List<OpportunityContactRole> roles = existingByContact.get(cId);
                for (Integer i = 1; i < roles.size(); i++) {
                    toDelete.add(roles[i]);
                }
                if (roles[0].IsPrimary) {
                    roles[0].IsPrimary = false;
                    toUpdate.add(roles[0]);
                }
            }
        }

        for (Id cId : desiredRoles.keySet()) {
            String role = desiredRoles.get(cId);
            Boolean primary = (cId == donor.Id);
            List<OpportunityContactRole> roles = existingByContact.get(cId);
            if (roles == null || roles.isEmpty()) {
                toInsert.add(new OpportunityContactRole(
                    OpportunityId = oppId,
                    ContactId = cId,
                    Role = role,
                    IsPrimary = primary
                ));
            } else {
                OpportunityContactRole keep = roles[0];
                if (keep.Role != role || keep.IsPrimary != primary) {
                    keep.Role = role;
                    keep.IsPrimary = primary;
                    toUpdate.add(keep);
                }
                for (Integer i = 1; i < roles.size(); i++) {
                    toDelete.add(roles[i]);
                }
            }
        }

        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    private static void reconcilePayment(Id oppId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> payments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c,
                   npe01__Scheduled_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :oppId
            ORDER BY CreatedDate ASC, Id ASC
        ];

        if (payments.isEmpty()) {
            insert new npe01__OppPayment__c(
                npe01__Opportunity__c = oppId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            return;
        }

        List<npe01__OppPayment__c> extras = new List<npe01__OppPayment__c>();
        for (Integer i = 1; i < payments.size(); i++) {
            extras.add(payments[i]);
        }
        if (!extras.isEmpty()) {
            delete extras;
        }

        npe01__OppPayment__c keep = payments[0];
        keep.npe01__Payment_Amount__c = amount;
        keep.npe01__Payment_Date__c = giftDate;
        keep.npe01__Scheduled_Date__c = giftDate;
        keep.npe01__Paid__c = true;
        update keep;
    }

    private static String getClosedWonStage() {
        List<OpportunityStage> stages = [
            SELECT ApiName
            FROM OpportunityStage
            WHERE IsActive = true AND IsClosed = true AND IsWon = true
            ORDER BY SortOrder ASC
            LIMIT 1
        ];
        if (stages.isEmpty()) {
            return 'Closed Won';
        }
        return stages[0].ApiName;
    }

    private static String buildName(Contact c, Date d) {
        String fullName = (String.isBlank(c.FirstName) ? '' : c.FirstName + ' ') + c.LastName;
        String dateStr = Datetime.newInstance(d.year(), d.month(), d.day()).format('yyyy-MM-dd');
        return fullName + ' Donation ' + dateStr;
    }
}
```

**Contact roles**
- Every household member ends up with exactly one role: Donor (primary) for the contact, Household Member for everyone else.
- If NPSP created more than one role for a contact, the extras are deleted.
- Contacts outside the household that NPSP may have added (for example, soft-credit relationships) are left in place, but reduced to one role each and not marked primary.

**Payments**
- One payment is kept, or created if NPSP made none.
- That payment is set to paid, for the full amount, with both payment date and scheduled date set to `giftDate`. Any extra payments are deleted.

**Assumptions**
- The Closed Won stage is looked up from `OpportunityStage` rather than hard-coded, in case the org renamed it. It falls back to `'Closed Won'` if none is found.
- If the contact has no household account, the method throws an `IllegalArgumentException`.
- The class runs `with sharing`, so the volunteer user needs create/edit access on Opportunity, OpportunityContactRole and `npe01__OppPayment__c`.

