/**
 * Links child Contacts to their parent Contacts using NPSP Relationships.
 *
 * Only ONE relationship record is inserted per pair: the child's view, where
 * Contact = child, RelatedContact = parent and Type = 'Parent'. NPSP's
 * relationship trigger then creates the reciprocal record automatically. With
 * the "List Setting" method, the reciprocal type is Son, Daughter or Child,
 * resolved from the child's gender through the Relationship Lookup setting.
 *
 * Inserting both directions ourselves would cause NPSP to create extra
 * reciprocals and leave duplicate records, so we deliberately do not do that.
 */
public with sharing class FamilyService {

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect the valid pairs. Skip nulls and self-references.
        Set<Id> contactIds = new Set<Id>();
        Map<Id, Id> candidates = new Map<Id, Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            candidates.put(childId, parentId);
            contactIds.add(childId);
            contactIds.add(parentId);
        }
        if (candidates.isEmpty()) {
            return;
        }

        // One query: find any existing relationship between the involved contacts.
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
              AND npe4__RelatedContact__c IN :contactIds
        ]) {
            existingPairs.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        Set<String> seen = new Set<String>();
        for (Id childId : candidates.keySet()) {
            Id parentId = candidates.get(childId);
            String key = pairKey(childId, parentId);
            // Skip pairs that already exist in either direction, or that
            // appear twice in this input (e.g. A->B and B->A).
            if (existingPairs.contains(key) || seen.contains(key)) {
                continue;
            }
            seen.add(key);
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            ));
        }

        // One DML statement.
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    // Order-independent key, so a relationship in either direction matches.
    private static String pairKey(Id a, Id b) {
        String sa = String.valueOf(a);
        String sb = String.valueOf(b);
        return sa < sb ? sa + ':' + sb : sb + ':' + sa;
    }
}
