File: force-app/main/default/classes/OPP_MajorGiftFollowUp_TDTM.cls
```apex
/**
 * NPSP TDTM handler. It creates a "Major gift thank-you call" Task when an Opportunity
 * becomes Closed Won with Amount >= 5000.
 *
 * Register it with an npsp__Trigger_Handler__c record:
 *   Class = OPP_MajorGiftFollowUp_TDTM, Object = Opportunity,
 *   Trigger Action = AfterInsert;AfterUpdate, Load Order = 5, Asynchronous = false.
 *
 * There is no Apex trigger. NPSP's TDTM dispatcher calls run(). Deactivating the
 * Trigger Handler record stops this logic from running.
 *
 * Governor usage per transaction: at most 1 SOQL query (won stage values) and no DML of
 * its own. The Tasks are returned in the DmlWrapper, and NPSP's dispatcher inserts them
 * in a single bulk DML.
 */
global without sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    @TestVisible
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    @TestVisible
    private static final String TASK_SUBJECT = 'Major gift thank-you call';

    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        Boolean isInsert = triggerAction == npsp.TDTM_Runnable.Action.AfterInsert;
        Boolean isUpdate = triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate;
        if ((!isInsert && !isUpdate) || newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>();
        if (isUpdate && oldlist != null) {
            for (SObject so : oldlist) {
                oldMap.put(so.Id, (Opportunity) so);
            }
        }

        // Cheap pre-filter on Amount, so the query only runs when it is needed.
        List<Opportunity> candidates = new List<Opportunity>();
        for (SObject so : newlist) {
            Opportunity opp = (Opportunity) so;
            if (meetsAmount(opp)) {
                candidates.add(opp);
            }
        }
        if (candidates.isEmpty()) {
            return dmlWrapper;
        }

        // Single SOQL: resolve which stage values count as Closed Won.
        Set<String> wonStages = new Set<String>();
        for (OpportunityStage st : [
            SELECT ApiName FROM OpportunityStage WHERE IsWon = true AND IsClosed = true
        ]) {
            wonStages.add(st.ApiName);
        }

        List<Task> tasks = new List<Task>();
        for (Opportunity opp : candidates) {
            if (!wonStages.contains(opp.StageName)) {
                continue;
            }
            if (isUpdate) {
                Opportunity oldOpp = oldMap.get(opp.Id);
                // Skip gifts that already qualified before this update.
                if (oldOpp != null && meetsAmount(oldOpp) && wonStages.contains(oldOpp.StageName)) {
                    continue;
                }
            }
            tasks.add(new Task(
                Subject = TASK_SUBJECT,
                Priority = 'High',
                Status = 'Not Started',
                WhatId = opp.Id,
                WhoId = (Id) opp.get('npsp__Primary_Contact__c'),
                OwnerId = opp.OwnerId,
                ActivityDate = opp.CloseDate == null ? null : opp.CloseDate.addDays(3)
            ));
        }

        if (!tasks.isEmpty()) {
            dmlWrapper.objectsToInsert.addAll((List<SObject>) tasks);
        }
        return dmlWrapper;
    }

    private static Boolean meetsAmount(Opportunity opp) {
        return opp.Amount != null && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }
}
```

Design notes:
- **Class declaration.** The class is `global` and overrides `run` as `global override`. This is required when extending NPSP's managed `npsp.TDTM_Runnable`.
- **Detecting Closed Won.** Closed Won is resolved from `OpportunityStage` (`IsWon = true`), not hard-coded, so it respects custom stage names. That lookup is the handler's only SOQL query. It is skipped entirely when no record in the batch has Amount >= 5000.
- **No DML of its own.** The handler returns Tasks in `DmlWrapper.objectsToInsert`. NPSP's dispatcher then inserts them in one bulk DML statement. This keeps the handler within the "1 query / 1 DML" budget for 200 records.
- **No duplicate tasks.** On update, a task is created only when the old version did not already meet both conditions. Editing a gift that already qualified therefore creates nothing.
- **Running only through TDTM.** There is no Apex trigger. The logic runs only when the active `npsp__Trigger_Handler__c` record tells TDTM to call it, and stops when the admin deactivates that record.

