/**
 * Trigger action (After Insert on Account): creates an onboarding Task for the owner of each
 * newly created customer account (Type 'Customer - Direct' or 'Customer - Channel').
 * Bulk-safe: one DML statement per execution, no DML when no account qualifies.
 */
public with sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {
    @TestVisible
    private static final Set<String> CUSTOMER_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };
    @TestVisible
    private static final String TASK_SUBJECT = 'Onboard new customer';
    @TestVisible
    private static final Integer DAYS_UNTIL_DUE = 7;

    public void afterInsert(List<SObject> triggerNew) {
        List<Task> tasks = new List<Task>();
        Date dueDate = Date.today().addDays(DAYS_UNTIL_DUE);
        for (Account acc : (List<Account>) triggerNew) {
            if (acc.Type != null && CUSTOMER_TYPES.contains(acc.Type)) {
                tasks.add(
                    new Task(
                        Subject = TASK_SUBJECT,
                        WhatId = acc.Id,
                        OwnerId = acc.OwnerId,
                        ActivityDate = dueDate,
                        Status = 'Not Started',
                        Priority = 'Normal'
                    )
                );
            }
        }
        if (!tasks.isEmpty()) {
            insert as user tasks;
        }
    }
}
```

