/**
 * Trigger action (Trigger Actions Framework) that prevents two Contacts of the same
 * Account from sharing an email address (case-insensitive).
 * Registered for Contact before insert and before update.
 *
 * Runs without sharing so the check sees every contact on the account,
 * including contacts the running user cannot see.
 */
public without sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    @TestVisible
    private static final String ERROR_MESSAGE = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        validate((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        validate((List<Contact>) triggerNew, new Map<Id, SObject>(triggerOld));
    }

    private void validate(List<Contact> contacts, Map<Id, SObject> oldMap) {
        List<Contact> toCheck = new List<Contact>();
        List<Contact> unchanged = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        Set<Id> batchIds = new Set<Id>();

        for (Contact c : contacts) {
            if (c.Id != null) {
                batchIds.add(c.Id);
            }
            if (!isCheckable(c)) {
                continue;
            }
            Boolean changed = true;
            if (oldMap != null) {
                Contact old = (Contact) oldMap.get(c.Id);
                changed = old == null
                    || old.AccountId != c.AccountId
                    || normalize(old.Email) != normalize(c.Email);
            }
            if (changed) {
                toCheck.add(c);
                accountIds.add(c.AccountId);
                emails.add(c.Email.trim().toLowerCase());
            } else {
                unchanged.add(c);
            }
        }

        if (toCheck.isEmpty()) {
            return;
        }

        // Keys already in use by contacts outside this save (SOQL email comparison is case-insensitive).
        Set<String> takenKeys = new Set<String>();
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
                AND Email IN :emails
                AND Id NOT IN :batchIds
        ]) {
            takenKeys.add(key(existing));
        }

        // Unchanged contacts in this save keep their address and still occupy it.
        for (Contact c : unchanged) {
            takenKeys.add(key(c));
        }

        // The first contact in the list wins; later contacts with the same key are rejected.
        Set<String> seenInBatch = new Set<String>();
        for (Contact c : toCheck) {
            String k = key(c);
            if (takenKeys.contains(k) || seenInBatch.contains(k)) {
                c.addError(ERROR_MESSAGE);
            } else {
                seenInBatch.add(k);
            }
        }
    }

    private static Boolean isCheckable(Contact c) {
        return c.AccountId != null && String.isNotBlank(c.Email);
    }

    private static String normalize(String email) {
        return email == null ? null : email.trim().toLowerCase();
    }

    private static String key(Contact c) {
        return String.valueOf(c.AccountId).left(15) + '|' + normalize(c.Email);
    }
}
