/**
 * Trigger action that keeps Account.FB_Open_Case_Count__c equal to the number of
 * the account's Cases with IsClosed = false.
 * Registered for after insert, after update, after delete and after undelete on Case.
 * Runs without sharing so the roll-up counts all cases regardless of the running user's access.
 */
public without sharing class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {
	public void afterInsert(List<SObject> triggerNew) {
		recalculate(collectAccountIds(triggerNew));
	}

	public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
		Map<Id, Case> oldMap = new Map<Id, Case>((List<Case>) triggerOld);
		Set<Id> accountIds = new Set<Id>();
		for (Case newCase : (List<Case>) triggerNew) {
			Case oldCase = oldMap.get(newCase.Id);
			if (oldCase == null) {
				continue;
			}
			if (newCase.AccountId != oldCase.AccountId || newCase.IsClosed != oldCase.IsClosed) {
				if (newCase.AccountId != null) {
					accountIds.add(newCase.AccountId);
				}
				if (oldCase.AccountId != null) {
					accountIds.add(oldCase.AccountId);
				}
			}
		}
		recalculate(accountIds);
	}

	public void afterDelete(List<SObject> triggerOld) {
		recalculate(collectAccountIds(triggerOld));
	}

	public void afterUndelete(List<SObject> triggerNew) {
		recalculate(collectAccountIds(triggerNew));
	}

	private static Set<Id> collectAccountIds(List<SObject> records) {
		Set<Id> accountIds = new Set<Id>();
		for (Case c : (List<Case>) records) {
			if (c.AccountId != null) {
				accountIds.add(c.AccountId);
			}
		}
		return accountIds;
	}

	private static void recalculate(Set<Id> accountIds) {
		if (accountIds == null || accountIds.isEmpty()) {
			return;
		}

		Map<Id, Integer> openCounts = new Map<Id, Integer>();
		for (Id accountId : accountIds) {
			openCounts.put(accountId, 0);
		}

		for (AggregateResult ar : [
			SELECT AccountId accId, COUNT(Id) cnt
			FROM Case
			WHERE AccountId IN :accountIds AND IsClosed = FALSE
			GROUP BY AccountId
		]) {
			openCounts.put((Id) ar.get('accId'), (Integer) ar.get('cnt'));
		}

		List<Account> toUpdate = new List<Account>();
		for (Account acc : [
			SELECT Id, FB_Open_Case_Count__c
			FROM Account
			WHERE Id IN :accountIds
		]) {
			Integer newCount = openCounts.get(acc.Id);
			if (acc.FB_Open_Case_Count__c == null || acc.FB_Open_Case_Count__c.intValue() != newCount) {
				toUpdate.add(new Account(Id = acc.Id, FB_Open_Case_Count__c = newCount));
			}
		}

		if (!toUpdate.isEmpty()) {
			update toUpdate;
		}
	}
}
