/**
 * After-update Trigger Action: creates one completed "Amount changed" Task when an
 * Opportunity's Amount changes. Updates made later in the same transaction as a consequence
 * of the original change (e.g. TA_Opportunity_RoundAmount) are not logged again.
 */
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    @TestVisible
    private static final String TASK_SUBJECT = 'Amount changed';
    @TestVisible
    private static final String TASK_STATUS = 'Completed';

    /**
     * Last Amount seen as "new" for each opportunity in this transaction. If a later update's
     * old Amount equals this value, that update continues the same chain (recursion caused
     * by the original update) and is not logged. On a partial-success retry, the old values
     * revert to the originals, so those records are processed again, which is correct because
     * the earlier Task insert was rolled back.
     */
    private static Map<Id, Decimal> lastSeenAmountById = new Map<Id, Decimal>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>(triggerOld);
        List<Task> tasks = new List<Task>();

        for (Opportunity opp : triggerNew) {
            Opportunity oldOpp = oldMap.get(opp.Id);
            Boolean isContinuation = lastSeenAmountById.containsKey(opp.Id)
                && lastSeenAmountById.get(opp.Id) == oldOpp.Amount;

            if (!isContinuation && opp.Amount != oldOpp.Amount) {
                tasks.add(new Task(
                    Subject = TASK_SUBJECT,
                    WhatId = opp.Id,
                    Status = TASK_STATUS
                ));
            }
            lastSeenAmountById.put(opp.Id, opp.Amount);
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
